-- MVP map, generated by script so it is reproducible (SPEC MVP, PLAN 1.8).
-- A fresh surface whose map gen makes only grass inside a fixed rectangle; water, ore, coal
-- and the cities are placed by this module at fixed positions.
local config = require("shared.config")
local cities = require("scripts.cities")

local M = {}

M.SURFACE = "train-tycoon"

-- Map is WIDTH x HEIGHT tiles centred on {0, 0}.
M.WIDTH, M.HEIGHT = 640, 400
M.SPAWN = { x = 0, y = 4 }

-- City centres (9x9 cities sit on tile centres).
M.CITIES = {
  -- label/tag_icon: the map tag (tag text is a plain string, not localised)
  { name = config.CITY.depot, x = 0, y = -24, label = "Depot city", tag_icon = "tt-coal-fuel" }, -- near the start
  { name = config.CITY.power, x = -64, y = 40, label = "Power city", tag_icon = "small-electric-pole" },
  { name = config.CITY.iron, x = 160, y = -96, label = "Iron smelting city", tag_icon = "iron-plate" },
  { name = config.CITY.copper, x = 160, y = 96, label = "Copper smelting city", tag_icon = "copper-plate" },
  { name = config.CITY.goal, x = 272, y = 0, label = "Goal box", tag_icon = "iron-chest" },
}

-- Resource patches: centre, radius (tiles), amount at the centre (falls off to half at the edge).
M.PATCHES = {
  { name = "iron-ore", x = -240, y = -140, radius = 14, amount = 4000 },
  { name = "copper-ore", x = -240, y = 140, radius = 14, amount = 4000 },
  { name = "coal", x = -40, y = -165, radius = 12, amount = 4000 },
}

-- Lake (deep water in the middle).
M.LAKE = { x = 60, y = 165, radius = 10 }

-- Starting inventory: a little coal fuel to hand-fuel the first train (SPEC: hand-fueling
-- helps at the start). Everything else is free to hand-craft.
M.START_ITEMS = { { name = "tt-coal-fuel", count = 20 } }

function M.map_gen_settings()
  return {
    seed = 1,
    width = M.WIDTH,
    height = M.HEIGHT,
    starting_points = { M.SPAWN },
    no_enemies_mode = true,
    peaceful_mode = true,
    default_enable_all_autoplace_controls = false,
    autoplace_controls = {},
    autoplace_settings = {
      tile = { treat_missing_as_default = false, settings = { ["grass-1"] = { frequency = 1, size = 1, richness = 1 } } },
      entity = { treat_missing_as_default = false, settings = {} },
      decorative = { treat_missing_as_default = false, settings = {} },
    },
    cliff_settings = { name = "cliff", cliff_elevation_0 = 1024, cliff_elevation_interval = 10, richness = 0 },
  }
end

local function circle(cx, cy, r, fn)
  for x = math.floor(cx - r), math.ceil(cx + r) do
    for y = math.floor(cy - r), math.ceil(cy + r) do
      local d = math.sqrt((x + 0.5 - cx) ^ 2 + (y + 0.5 - cy) ^ 2)
      if d <= r then fn(x, y, d) end
    end
  end
end

---@param surface LuaSurface
local function place_lake(surface)
  local tiles = {}
  circle(M.LAKE.x, M.LAKE.y, M.LAKE.radius, function(x, y, d)
    tiles[#tiles + 1] = { name = d < M.LAKE.radius * 0.6 and "deepwater" or "water", position = { x, y } }
  end)
  surface.set_tiles(tiles)
end

---@param surface LuaSurface
local function place_patches(surface)
  for _, p in ipairs(M.PATCHES) do
    circle(p.x, p.y, p.radius, function(x, y, d)
      local amount = math.floor(p.amount * (1 - 0.5 * d / p.radius))
      surface.create_entity({ name = p.name, position = { x + 0.5, y + 0.5 }, amount = amount })
    end)
  end
end

---@param surface LuaSurface
local function place_cities(surface)
  for _, c in ipairs(M.CITIES) do
    cities.place(c.name, surface, { c.x + 0.5, c.y + 0.5 }, "player")
  end
end

--- Put a labelled map tag on every city of the surface. Charting is asynchronous, so tags
--- that can't be placed yet are retried from tick_tags (storage.tt_map_tags_pending).
---@param surface LuaSurface
local function tag_cities(surface)
  storage.tt_map_tags_pending = storage.tt_map_tags_pending or {}
  storage.tt_map_tags_pending[surface.name] = true
end

--- Place pending city map tags (called every GOAL_TICK_INTERVAL). Returns tags placed.
function M.tick_tags()
  local pending = storage.tt_map_tags_pending
  if not pending then return 0 end
  local placed = 0
  for surface_name in pairs(pending) do
    local surface = game.get_surface(surface_name)
    if not surface then
      pending[surface_name] = nil
    else
      local force = game.forces["player"]
      local all = true
      for _, c in ipairs(M.CITIES) do
        local pos = { x = c.x + 0.5, y = c.y + 0.5 }
        if #force.find_chart_tags(surface, { { pos.x - 1, pos.y - 1 }, { pos.x + 1, pos.y + 1 } }) == 0 then
          local tag = force.add_chart_tag(surface, {
            position = pos,
            icon = { type = "item", name = c.tag_icon },
            text = c.label,
          })
          if tag then placed = placed + 1 else all = false end
        end
      end
      if all then pending[surface_name] = nil end
    end
  end
  return placed
end

--- Create (if needed) and populate the map surface. Returns the surface.
---@param name string? surface name (default M.SURFACE)
function M.generate(name)
  name = name or M.SURFACE
  local surface = game.get_surface(name)
  if surface then return surface end
  surface = game.create_surface(name, M.map_gen_settings())
  local chunk_radius = math.ceil(math.max(M.WIDTH, M.HEIGHT) / 2 / 32) + 1
  surface.request_to_generate_chunks({ 0, 0 }, chunk_radius)
  surface.force_generate_chunk_requests()
  place_lake(surface)
  place_patches(surface)
  place_cities(surface)
  game.forces["player"].chart(surface, { { -M.WIDTH / 2, -M.HEIGHT / 2 }, { M.WIDTH / 2, M.HEIGHT / 2 } })
  tag_cities(surface)
  return surface
end

--- Move a player to the map and give the starting items (once).
---@param player LuaPlayer
function M.setup_player(player)
  local surface = M.generate()
  local pos = surface.find_non_colliding_position("character", M.SPAWN, 20, 0.5) or M.SPAWN
  player.teleport(pos, surface)
  storage.tt_map_started = storage.tt_map_started or {}
  if not storage.tt_map_started[player.index] then
    storage.tt_map_started[player.index] = true
    for _, stack in ipairs(M.START_ITEMS) do player.insert(stack) end
  end
end

function M.remote_interface()
  return {
    generate = function(name) return M.generate(name) end,
    tick_tags = function() return M.tick_tags() end,
    setup_player = function(player_index) M.setup_player(assert(game.get_player(player_index))) end,
    layout = function()
      return { width = M.WIDTH, height = M.HEIGHT, spawn = M.SPAWN, cities = M.CITIES,
        patches = M.PATCHES, lake = M.LAKE }
    end,
  }
end

return M
